var n=`0137-ojakhuri`;var i=`world-0137`;var o=`GE`;var a=`western-asia`;var s=4;var r=45;var l={en:`Ojakhuri`,ua:`Оджахурі`};var u={en:`A classic dish from Georgia, featuring pork shoulder, potato, yellow onion, garlic. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Грузія. Основні складники: свиняча лопатка, картопля, жовта цибуля, часник. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`pork-shoulder`,650,`g`],[`sunflower-oil`,50,`ml`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 20 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 20 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:20,i:[[`potato`,750,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,230,`g`],[`garlic`,4,`clove`],[`sweet-paprika`,9,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`cilantro`,22,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]}];var g={slug:n,id:i,country:`GE`,region:a,servings:4,minutes:45,title:l,text:u,steps:d};export{o as country,g as default,i as id,r as minutes,a as region,s as servings,n as slug,d as steps,u as text,l as title};